import express from 'express';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3000;

const DATA_FILES = [
  path.join(__dirname, 'data.json'),
  path.join(__dirname, 'books.json'),
  path.join(__dirname, 'data', 'books.json'),
];

const PRIMARY_FILE = DATA_FILES[0];

for (const f of [path.join(__dirname, 'data')]) {
  if (!fs.existsSync(f)) fs.mkdirSync(f, { recursive: true });
}

function loadBooks() {
  for (const file of DATA_FILES) {
    if (fs.existsSync(file)) {
      try {
        const raw = fs.readFileSync(file, 'utf8');
        if (!raw.trim()) return [];
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return parsed;
        if (Array.isArray(parsed.books)) return parsed.books;
      } catch {}
    }
  }
  return [];
}

function saveBooks(books) {
  const data = JSON.stringify(books, null, 2);
  for (const file of DATA_FILES) {
    try {
      const dir = path.dirname(file);
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(file, data, 'utf8');
    } catch {}
  }
}

function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function escapeHtml(str = '') {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

app.use(express.urlencoded({ extended: true }));
app.use(express.json());

app.get('/api/books', (req, res) => {
  res.json(loadBooks());
});

app.get('/api/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) return res.status(404).json({ error: 'Not found' });
  res.json(book);
});

app.post('/api/books', (req, res) => {
  const { title, author, notes } = req.body;
  if (!title || !String(title).trim()) return res.status(400).json({ error: 'Title required' });
  const books = loadBooks();
  const book = {
    id: generateId(),
    title: String(title).trim(),
    author: String(author || '').trim(),
    notes: String(notes || '').trim(),
    status: 'reading',
    createdAt: new Date().toISOString(),
  };
  books.push(book);
  saveBooks(books);
  res.status(201).json(book);
});

app.post('/api/books/:id/finish', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) return res.status(404).json({ error: 'Not found' });
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  saveBooks(books);
  res.json(book);
});

app.patch('/api/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) return res.status(404).json({ error: 'Not found' });
  if (req.body.status === 'finished' || req.body.finished === true) {
    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
  }
  if (typeof req.body.title === 'string') book.title = req.body.title;
  if (typeof req.body.author === 'string') book.author = req.body.author;
  if (typeof req.body.notes === 'string') book.notes = req.body.notes;
  saveBooks(books);
  res.json(book);
});

function renderLayout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
*{box-sizing:border-box}body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:800px;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}
h1{margin:0 0 1rem}h2{border-bottom:1px solid #ddd;padding-bottom:.4rem}
.book{border:1px solid #ddd;padding:.8rem 1rem;border-radius:8px;margin:.6rem 0;background:#fafafa}
.book a{font-weight:600;color:#0b57d0;text-decoration:none}.book a:hover{text-decoration:underline}
form{border:1px solid #ddd;padding:1rem;border-radius:8px;margin:1.5rem 0;background:#f9f9f9}
label{display:block;margin:.5rem 0 .2rem;font-weight:600}
input,textarea{width:100%;padding:.5rem;border:1px solid #ccc;border-radius:6px}
button{margin-top:.8rem;padding:.6rem 1rem;border:0;border-radius:6px;background:#0b57d0;color:white;cursor:pointer}
button:hover{background:#08419e}
.muted{color:#666;font-size:.9rem}
.actions{margin-top:.5rem}
.inline-form{display:inline}
.inline-form button{padding:.3rem .7rem;font-size:.85rem;margin:0}
.detail{border:1px solid #ddd;padding:1.5rem;border-radius:8px;background:#fff}
.share{margin:1rem 0;padding:.8rem;background:#eef2ff;border-radius:6px;word-break:break-all}
a{color:#0b57d0}
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function renderHome(books) {
  const reading = books.filter(b => b.status !== 'finished');
  const finished = books.filter(b => b.status === 'finished');

  const bookHtml = (b) => `
    <div class="book" data-id="${escapeHtml(b.id)}" data-status="${escapeHtml(b.status)}">
      <a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>
      ${b.author ? `<div class="muted">by ${escapeHtml(b.author)}</div>` : ''}
      ${b.notes ? `<div style="margin-top:.4rem">${escapeHtml(b.notes)}</div>` : ''}
      <div class="actions">
        ${b.status !== 'finished' ? `<form class="inline-form" method="POST" action="/books/${escapeHtml(b.id)}/finish"><button type="submit">Mark as finished</button></form>` : `<span class="muted">Finished${b.finishedAt ? ' on ' + escapeHtml(new Date(b.finishedAt).toLocaleDateString()) : ''}</span>`}
        <a href="/books/${escapeHtml(b.id)}" style="margin-left:.8rem;font-size:.9rem">View details</a>
      </div>
    </div>
  `;

  return renderLayout('My Books', `
    <h1>My Books</h1>
    <p class="muted">Track what you're reading. Share a book via its detail link.</p>

    <form method="POST" action="/books" id="add-book-form">
      <h3 style="margin-top:0">Add a book</h3>
      <label for="title">Title *</label>
      <input id="title" name="title" required placeholder="e.g. Dune">
      <label for="author">Author</label>
      <input id="author" name="author" placeholder="e.g. Frank Herbert">
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" rows="3" placeholder="Your notes..."></textarea>
      <button type="submit">Add book</button>
    </form>

    <h2>Currently Reading</h2>
    ${reading.length ? reading.map(bookHtml).join('') : '<p class="muted">Nothing currently reading. Add a book above.</p>'}

    <h2>Finished</h2>
    ${finished.length ? finished.map(bookHtml).join('') : '<p class="muted">No finished books yet.</p>'}

    <p class="muted" style="margin-top:2rem">Books are saved to a JSON file and persist after restart.</p>
  `);
}

function renderDetail(book, req) {
  const url = `${req.protocol}://${req.get('host')}${req.originalUrl}`;
  return renderLayout(book.title, `
    <p><a href="/">← Back to list</a></p>
    <div class="detail">
      <h1 style="margin-top:0">${escapeHtml(book.title)}</h1>
      ${book.author ? `<p><strong>Author:</strong> ${escapeHtml(book.author)}</p>` : '<p class="muted">No author</p>'}
      <p><strong>Status:</strong> ${escapeHtml(book.status)}${book.finishedAt ? ' (finished on ' + escapeHtml(new Date(book.finishedAt).toLocaleDateString()) + ')' : ''}</p>
      ${book.notes ? `<p><strong>Notes:</strong><br>${escapeHtml(book.notes).replace(/\\n/g,'<br>')}</p>` : '<p class="muted">No notes</p>'}
      ${book.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish"><button type="submit">Mark as finished</button></form>` : ''}
      <div class="share">
        <strong>Shareable link:</strong><br>
        <a href="${escapeHtml(url)}" id="share-link">${escapeHtml(url)}</a>
        <div class="muted" style="margin-top:.4rem">Send this link to someone to show this book.</div>
      </div>
    </div>
  `);
}

app.get('/', (req, res) => {
  res.send(renderHome(loadBooks()));
});

app.get('/books/:id', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) return res.status(404).send(renderLayout('Not found', '<h1>Book not found</h1><p><a href="/">Back to list</a></p>'));
  res.send(renderDetail(book, req));
});

app.post('/books', (req, res) => {
  const title = req.body.title?.trim();
  const author = req.body.author?.trim() || '';
  const notes = req.body.notes?.trim() || '';
  if (!title) {
    if (req.headers.accept?.includes('application/json')) return res.status(400).json({ error: 'Title required' });
    return res.status(400).send(renderLayout('Error', '<p>Title is required</p><a href="/">Back</a>'));
  }
  const books = loadBooks();
  const book = {
    id: generateId(),
    title,
    author,
    notes,
    status: 'reading',
    createdAt: new Date().toISOString(),
  };
  books.push(book);
  saveBooks(books);
  if (req.headers.accept?.includes('application/json')) return res.status(201).json(book);
  const wantsJson = req.headers['content-type']?.includes('application/json');
  if (wantsJson) return res.status(201).json(book);
  res.redirect('/');
});

app.post('/books/:id/finish', (req, res) => {
  const books = loadBooks();
  const book = books.find(b => String(b.id) === String(req.params.id));
  if (!book) {
    if (req.headers.accept?.includes('application/json')) return res.status(404).json({ error: 'Not found' });
    return res.status(404).send('Not found');
  }
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  saveBooks(books);
  if (req.headers.accept?.includes('application/json')) return res.json(book);
  const referer = req.get('referer') || '/';
  if (referer.includes(`/books/${book.id}`)) return res.redirect(`/books/${book.id}`);
  res.redirect('/');
});

app.get('/health', (req, res) => res.json({ ok: true }));

app.use((req, res) => {
  res.status(404).send(renderLayout('404', '<h1>Not found</h1><p><a href="/">Back home</a></p>'));
});

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  app.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
    console.log(`Data files: ${DATA_FILES.join(', ')}`);
  });
}

export default app;

