*{box-sizing:border-box}body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:800px;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}
h1{margin:0 0 1rem}h2{border-bottom:1px solid #ddd;padding-bottom:.4rem}
.book{border:1px solid #ddd;padding:.8rem 1rem;border-radius:8px;margin:.6rem 0;background:#fafafa}
.book a{font-weight:600;color:#0b57d0;text-decoration:none}.book a:hover{text-decoration:underline}
form{border:1px solid #ddd;padding:1rem;border-radius:8px;margin:1.5rem 0;background:#f9f9f9}
label{display:block;margin:.5rem 0 .2rem;font-weight:600}
input,textarea{width:100%;padding:.5rem;border:1px solid #ccc;border-radius:6px}
button{margin-top:.8rem;padding:.6rem 1rem;border:0;border-radius:6px;background:#0b57d0;color:white;cursor:pointer}
button:hover{background:#08419e}
.muted{color:#666;font-size:.9rem}
.actions{margin-top:.5rem}
.inline-form{display:inline}
.inline-form button{padding:.3rem .7rem;font-size:.85rem;margin:0}
.detail{border:1px solid #ddd;padding:1.5rem;border-radius:8px;background:#fff}
.share{margin:1rem 0;padding:.8rem;background:#eef2ff;border-radius:6px;word-break:break-all}
a{color:#0b57d0}
</style>
</head>
<body>

    <h1>My Books</h1>
    <p class="muted">Track what you're reading. Share a book via its detail link.</p>

    <form method="POST" action="/books" id="add-book-form">
      <h3 style="margin-top:0">Add a book</h3>
      <label for="title">Title *</label>
      <input id="title" name="title" required placeholder="e.g. Dune">
      <label for="author">Author</label>
      <input id="author" name="author" placeholder="e.g. Frank Herbert">
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" rows="3" placeholder="Your notes..."></textarea>
      <button type="submit">Add book</button>
    </form>

    <h2>Currently Reading</h2>
    <p class="muted">Nothing currently reading. Add a book above.</p>

    <h2>Finished</h2>
    <p class="muted">No finished books yet.</p>

    <p class="muted" style="margin-top:2rem">Books are saved to a JSON file and persist after restart.</p>

</body>
